import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MissionStatus, MissionsService } from '../../api';

type MissionFilter = 'all' | MissionStatus;

@Component({
  selector: 'app-mission-list',
  templateUrl: './mission-list.html',
  styleUrl: './mission-list.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MissionList {
  private readonly missionsApi = inject(MissionsService);

  /** `undefined` until the first response lands; the template shows a loading row until then. */
  protected readonly missions = toSignal(this.missionsApi.listMissions());

  protected readonly filter = signal<MissionFilter>('all');

  /** Missions matching the selected filter, in API order. `undefined` while loading. */
  protected readonly visible = computed(() => {
    const all = this.missions();
    const selected = this.filter();
    if (all === undefined || selected === 'all') {
      return all;
    }
    return all.filter((mission) => mission.status === selected);
  });

  protected setFilter(value: string): void {
    if (value === 'open' || value === 'done') {
      this.filter.set(value);
    } else {
      this.filter.set('all');
    }
  }
}

@let list = missions();
@let shown = visible() ?? [];
@if (list === undefined) {
  <p class="loading" role="status">Loading missions…</p>
} @else if (list.length === 0) {
  <p class="empty">No missions on the board.</p>
} @else {
  <select class="filter" aria-label="Filter by status" (change)="setFilter($any($event.target).value)">
    <option value="all" [selected]="filter() === 'all'">All</option>
    <option value="open" [selected]="filter() === 'open'">Open</option>
    <option value="done" [selected]="filter() === 'done'">Done</option>
  </select>
  <p class="count">Showing {{ shown.length }} of {{ list.length }} missions</p>
  @if (shown.length === 0) {
    <p class="no-match">No missions match this filter.</p>
  } @else {
    <ul class="missions">
      @for (mission of shown; track mission.id) {
        <li class="mission" [class.done]="mission.status === 'done'">
          <span class="priority" [attr.aria-label]="'priority ' + mission.priority">P{{ mission.priority }}</span>
          <span class="title">{{ mission.title }}</span>
          <span class="status">{{ mission.status }}</span>
        </li>
      }
    </ul>
  }
}

